#!/bin/bash
# post-build-strip.sh — optional Xcode "Run Script" build phase for Release.
# Xcode's STRIP_INSTALLED_PRODUCT already strips on Archive/Install builds; this phase
# covers plain Release builds (Product > Build) that never go through install.
# Add AFTER the "Compile openFrameworks" phase, with Input Files = $(TARGET_BUILD_DIR)/$(EXECUTABLE_PATH).
# It strips a COPY for inspection? No — it strips the built product in place, Release only.
# dSYM is generated by Xcode before this phase (DEBUG_INFORMATION_FORMAT=dwarf-with-dsym),
# so stripping here does not destroy your crash-log symbols.
set -eu
[ "${CONFIGURATION:-}" = "Release" ] || { echo "post-build-strip: Debug — skipped"; exit 0; }
BIN="${TARGET_BUILD_DIR:?}/${EXECUTABLE_PATH:?}"
[ -f "$BIN" ] || { echo "post-build-strip: no binary at $BIN"; exit 0; }
# -x: remove local symbols, -S: remove debug symbol table entries. Keeps global/dynamic symbols the loader needs.
strip -x -S "$BIN"
echo "post-build-strip: stripped $BIN"
# Re-sign after stripping (ad-hoc in Debug-style builds; Archive re-signs with your identity anyway).
if [ "${CODE_SIGNING_ALLOWED:-YES}" != "NO" ]; then
  codesign --force --sign "${EXPANDED_CODE_SIGN_IDENTITY:--}" --entitlements "${TARGET_TEMP_DIR:-/tmp}/${PRODUCT_NAME:-app}.app.xcent" "$BIN" 2>/dev/null || \
  codesign --force --sign - "$BIN" 2>/dev/null || echo "post-build-strip: re-sign skipped (Archive will sign)"
fi
